import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const REPORTS_DIR = path.join(ROOT, 'reports');

// We will read from internal-link-graph.json generated by internal-link-audit.mjs
// if it doesn't exist, we fallback gracefully.
const GRAPH_FILE = path.join(REPORTS_DIR, 'internal-link-graph.json');
const OUT_FILE = path.join(REPORTS_DIR, 'internal-link-opportunities.json');

let graph = null;
if (fs.existsSync(GRAPH_FILE)) {
  try {
    const data = JSON.parse(fs.readFileSync(GRAPH_FILE, 'utf8'));
    graph = data.graph;
  } catch (e) {
    console.error("Could not parse internal-link-graph.json");
  }
}

const opportunities = [];

if (graph) {
  const allNodes = [...(graph.hubs || []), ...graph.tools, ...graph.blogs];
  
  // Track inbound links for all nodes
  const inboundCount = {};
  for (const node of allNodes) {
    inboundCount[node.path] = 0;
  }
  
  for (const node of allNodes) {
    const outbound = [
      ...(node.outbound.tools || []),
      ...(node.outbound.blogs || []),
      ...(node.outbound.hubs || []),
      ...(node.outbound.categories || []),
      node.outbound.primaryTool
    ].filter(Boolean);
    
    for (const link of outbound) {
      if (inboundCount[link] !== undefined) {
        inboundCount[link]++;
      }
    }
  }

  for (const node of allNodes) {
    const inLinks = inboundCount[node.path];
    
    if (inLinks === 0) {
      opportunities.push({
        page: node.path,
        type: node.type,
        issue: 'Orphan page (0 inbound internal links)',
        recommendation: 'Add contextual links from related hubs or parent pages.'
      });
    } else if (inLinks < 3) {
      opportunities.push({
        page: node.path,
        type: node.type,
        issue: `Weakly linked (${inLinks} inbound links)`,
        recommendation: 'Find sibling pages or related blog posts to add contextual links.'
      });
    }
    
    // Hub specific checks
    if (node.type === 'hub') {
      if (!node.outbound.tools || node.outbound.tools.length < 5) {
        opportunities.push({
          page: node.path,
          type: 'hub',
          issue: 'Hub is thin',
          recommendation: 'Ensure hub links out to at least 5 child tools.'
        });
      }
    }
  }
} else {
  opportunities.push({
    page: 'system',
    type: 'warning',
    issue: 'internal-link-graph.json not found',
    recommendation: 'Run npm run audit:links before running the intelligence engine.'
  });
}

// Deterministic sorting
opportunities.sort((a, b) => {
  if (a.type !== b.type) return a.type.localeCompare(b.type);
  if (a.page !== b.page) return a.page.localeCompare(b.page);
  return a.issue.localeCompare(b.issue);
});

fs.mkdirSync(REPORTS_DIR, { recursive: true });
fs.writeFileSync(OUT_FILE, JSON.stringify({
  generatedBy: "SEO OS - Internal Link Intelligence",
  opportunities
}, null, 2));

console.log(`✔ Generated reports/internal-link-opportunities.json (${opportunities.length} opportunities)`);
